<?php $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); $t=fn($k)=>$this->objLanguage->languageText('mod_registration_service_'.$k,'registration-service'); $ok=!empty($recoveryCompletion['ok']); ?>
<main class="chisimba-workspace registration-service" aria-labelledby="recovery-result-title"><h1 id="recovery-result-title"><?php echo $e($t($ok?'recovery_success_title':'recovery_failed_title')); ?></h1><div class="<?php echo $ok?'success':'error'; ?>" role="status"><?php echo $e($t($ok?'recovery_success':'recovery_failed')); ?></div><?php if($ok): ?><div class="chisimba-form-actions"><a class="button" href="<?php echo $e(rtrim((string)$this->getObject('altconfig','config')->getItem('KEWL_SITE_ROOT'),'/').'/'); ?>"><?php echo $e($t('sign_in')); ?></a></div><?php endif; ?></main>
